let yearNode=document.getElementById("year"),revealNodes=(yearNode&&(yearNode.textContent=(new Date).getFullYear()),document.querySelectorAll(".reveal")),revealObserver=new IntersectionObserver((e,r)=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("is-visible"),r.unobserve(e.target))})},{threshold:.15});revealNodes.forEach(e=>revealObserver.observe(e));